-- +goose Up

-- ADR 0018 slice 3: user groups. A user group is a persisted set of accounts that a repository grant can name as
-- group:<id>; a group may also carry a global role, which raises (never lowers) the level of its members at
-- authentication time. The table is user_groups, not groups, because a Group here is a repository group (ADR 0012).
--
-- Ids are UUIDv7 generated by the application (internal/ids, ADR 0023 section 4). provider_id is NULL for a local
-- group; a group of a deleted provider keeps its row and its members (ON DELETE SET NULL). external_id is the
-- provider's identifier of the group and is the only key a login claim or a SCIM request may match on.
CREATE TABLE public.user_groups (
    id uuid NOT NULL,
    provider_id uuid,
    external_id text DEFAULT ''::text NOT NULL,
    display_name text NOT NULL,
    source text NOT NULL,
    global_role text DEFAULT 'none'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_groups_pkey PRIMARY KEY (id),
    CONSTRAINT user_groups_provider_id_fkey FOREIGN KEY (provider_id) REFERENCES public.identity_providers(id) ON DELETE SET NULL,
    CONSTRAINT user_groups_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 255))),
    CONSTRAINT user_groups_global_role_check CHECK ((global_role = ANY (ARRAY['none'::text, 'member'::text, 'admin'::text]))),
    CONSTRAINT user_groups_source_check CHECK ((source = ANY (ARRAY['local'::text, 'scim'::text, 'claims'::text]))),
    CONSTRAINT user_groups_version_check CHECK ((version > 0))
);

-- A local group is found by its case-insensitive name; a provisioned group by its provider and external id.
CREATE UNIQUE INDEX user_groups_name_local_idx ON public.user_groups USING btree (lower(display_name)) WHERE (provider_id IS NULL);
CREATE UNIQUE INDEX user_groups_provider_external_id_idx ON public.user_groups USING btree (provider_id, external_id) WHERE (external_id <> ''::text);

CREATE TABLE public.user_group_members (
    group_id uuid NOT NULL,
    user_id uuid NOT NULL,
    source text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_group_members_pkey PRIMARY KEY (group_id, user_id),
    CONSTRAINT user_group_members_group_id_fkey FOREIGN KEY (group_id) REFERENCES public.user_groups(id) ON DELETE CASCADE,
    CONSTRAINT user_group_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE,
    CONSTRAINT user_group_members_source_check CHECK ((source = ANY (ARRAY['local'::text, 'scim'::text, 'claims'::text])))
);

-- Every authenticated request resolves "the groups of this user" (ADR 0023 section 5); the primary key leads with
-- group_id and cannot serve that lookup.
CREATE INDEX user_group_members_user_idx ON public.user_group_members USING btree (user_id, group_id);

-- ADR 0023 section 6: a membership change announces the user (user_group:<user id>), so the group ids cached on
-- every node for that account are evicted; a change to a group row (its global role, its deletion) announces the
-- whole scope, because every member of the group is affected. Both are statement-level and bounded like the
-- triggers of migration 000011. MySQL polls the scope epoch instead (ADR 0022).
-- +goose StatementBegin
CREATE FUNCTION public.notarx_notify_cache_statement_user_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    keys text[];
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO keys FROM (SELECT DISTINCT user_id::text AS k FROM new_rows LIMIT 65) limited;
    ELSIF TG_OP = 'DELETE' THEN
        SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO keys FROM (SELECT DISTINCT user_id::text AS k FROM old_rows LIMIT 65) limited;
    ELSE
        SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO keys FROM (
            SELECT user_id::text AS k FROM new_rows UNION SELECT user_id::text FROM old_rows LIMIT 65) limited;
    END IF;
    PERFORM public.notarx_announce_cache(TG_ARGV[0], keys);
    RETURN NULL;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER user_group_members_notify_cache_insert AFTER INSERT ON public.user_group_members REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_user_id('user_group');
CREATE TRIGGER user_group_members_notify_cache_update AFTER UPDATE ON public.user_group_members REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_user_id('user_group');
CREATE TRIGGER user_group_members_notify_cache_delete AFTER DELETE ON public.user_group_members REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_user_id('user_group');

CREATE TRIGGER user_groups_notify_cache_insert AFTER INSERT ON public.user_groups REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_scope('user_group');
CREATE TRIGGER user_groups_notify_cache_update AFTER UPDATE ON public.user_groups REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_scope('user_group');
CREATE TRIGGER user_groups_notify_cache_delete AFTER DELETE ON public.user_groups REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.notarx_notify_cache_statement_scope('user_group');
